#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Run VGGT-SLAM from source and save final eval outputs + RRD internally.

This script replaces the old wrapper-side post-processing path. It prepares
selected images, runs VGGT-SLAM, performs pose-Sim3 alignment, and saves:

  <output_rrd>
  <output_dir>/eval/pred_points.ply
  <output_dir>/eval/gt_points.ply
  <output_dir>/eval/pred_cameras.npz
  <output_dir>/eval/gt_cameras.npz
  <output_dir>/eval/meta.json

The benchmark shell should only call this source script and then compute metrics.
"""
from __future__ import annotations

import argparse
import fnmatch
import json
import os
import re
import shutil
import sys
import time
import types
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

# Keep local VGGT/SALAD resolution identical to main.py before importing solver.
_THIS_DIR = Path(__file__).resolve().parent
_REPO_ROOT = _THIS_DIR.parents[1]
for p in (_THIS_DIR, _REPO_ROOT):
    if str(p) not in sys.path:
        sys.path.insert(0, str(p))

_VGGT_REPO = os.environ.get("VGGT_REPO") or (_THIS_DIR / "vggt")
if _VGGT_REPO and Path(_VGGT_REPO).exists() and (Path(_VGGT_REPO) / "vggt").is_dir():
    sys.path.insert(0, str(Path(_VGGT_REPO).resolve()))
    print(f"[VGGT-SLAM] Pre-import local VGGT source: {Path(_VGGT_REPO).resolve()}")
_SALAD_REPO = _THIS_DIR / "salad"
if (_SALAD_REPO / "salad").is_dir():
    sys.path.insert(0, str(_SALAD_REPO.resolve()))
    print(f"[VGGT-SLAM] Pre-import local SALAD source: {_SALAD_REPO.resolve()}")

import cv2
import numpy as np
import torch
from tqdm.auto import tqdm

import vggt_slam.slam_utils as utils
from vggt_slam.export_rrd import export_solver_outputs, json_safe, sample_points, sanitize_name, voxel_downsample_numpy
from vggt_slam.local_weights import configure_vggt_slam_runtime, load_vggt_weights
from vggt_slam.solver import Solver
from vggt_slam.vggt_source import build_vggt_from_local_path


IMAGE_EXTS = {".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff"}


def collect_stem_to_path(folder: Path, exts: Iterable[str]) -> Dict[str, Path]:
    exts = {e.lower() for e in exts}
    if not folder.exists():
        return {}
    return {
        p.stem: p
        for p in sorted(folder.iterdir())
        if p.is_file() and p.suffix.lower() in exts
    }


def contiguous_select(items: Sequence[str], max_count: int) -> List[str]:
    items = list(items)
    if max_count <= 0 or len(items) <= max_count:
        return items
    return items[: int(max_count)]


def select_images(args: argparse.Namespace) -> Tuple[List[str], List[Path]]:
    scene_dir = Path(args.scene_dir).expanduser().resolve()
    images_dir = scene_dir / args.images_dir
    images = collect_stem_to_path(images_dir, IMAGE_EXTS)
    if not images:
        raise RuntimeError(f"No images found under {images_dir}")

    stems = sorted(images)
    if args.frame_glob and args.frame_glob != "*":
        stems = [s for s in stems if fnmatch.fnmatch(s, args.frame_glob)]
    if args.start > 0:
        stems = stems[int(args.start) :]
    if args.stride > 1:
        stems = stems[:: int(args.stride)]
    stems = contiguous_select(stems, int(args.num_views))
    if not stems:
        raise RuntimeError(f"No frames selected under {images_dir}")
    return stems, [images[s] for s in stems]


def round_down_to_multiple(x: int, multiple: int) -> int:
    if multiple <= 1:
        return int(x)
    return max(int(multiple), int(x) // int(multiple) * int(multiple))


def target_hw(height: int, width: int, max_side: int, size_multiple: int) -> Tuple[int, int]:
    h, w = int(height), int(width)
    if max_side > 0 and max(h, w) > int(max_side):
        scale = float(max_side) / float(max(h, w))
        h = max(1, int(round(h * scale)))
        w = max(1, int(round(w * scale)))
    h = round_down_to_multiple(h, size_multiple)
    w = round_down_to_multiple(w, size_multiple)
    return h, w


def materialize_images(
    image_paths: Sequence[Path],
    stems: Sequence[str],
    out_dir: Path,
    max_side: int,
    size_multiple: int,
    copy_images: bool,
) -> Tuple[List[Path], List[Dict[str, object]]]:
    marker = out_dir / ".mapanything_vggt_slam_input"
    if out_dir.exists():
        if not marker.exists():
            raise RuntimeError(
                f"Refusing to overwrite existing input folder without marker: {out_dir}. "
                "Choose a fresh --output_dir or remove it manually."
            )
        shutil.rmtree(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    marker.write_text("generated by third_party/vggt-slam/run_scene_to_rrd.py\n", encoding="utf-8")

    materialized: List[Path] = []
    metadata: List[Dict[str, object]] = []
    for i, (src, stem) in enumerate(zip(image_paths, stems)):
        dst = out_dir / f"{i:06d}__{sanitize_name(stem)}{src.suffix.lower()}"
        img = cv2.imread(str(src), cv2.IMREAD_COLOR)
        if img is None:
            raise RuntimeError(f"Cannot read image: {src}")
        src_h, src_w = img.shape[:2]
        dst_h, dst_w = target_hw(src_h, src_w, max_side=max_side, size_multiple=size_multiple)
        resized = (dst_h, dst_w) != (src_h, src_w)

        if resized or copy_images:
            if resized:
                img = cv2.resize(img, (dst_w, dst_h), interpolation=cv2.INTER_AREA)
            if not cv2.imwrite(str(dst), img):
                raise RuntimeError(f"Failed to write prepared image: {dst}")
        else:
            try:
                os.symlink(src, dst)
            except OSError:
                shutil.copy2(src, dst)

        materialized.append(dst)
        metadata.append(
            {
                "index": i,
                "stem": stem,
                "source": str(src),
                "prepared": str(dst),
                "source_size": {"height": src_h, "width": src_w},
                "prepared_size": {"height": dst_h, "width": dst_w},
                "resized": resized,
            }
        )
    return materialized, metadata


def ensure_collect_sampled_points(graph_map) -> None:
    """Patch older GraphMap instances that do not yet expose collect_sampled_points."""
    if hasattr(graph_map, "collect_sampled_points"):
        return

    def collect_sampled_points(
        self,
        max_points=500000,
        voxel_size=0.01,
        seed=0,
        point_stride=1,
        per_submap_factor=2.0,
    ):
        submaps = list(self.ordered_submaps_by_key())
        num_submaps = max(1, len(submaps))
        if int(max_points) > 0:
            per_submap_cap = max(1, int(np.ceil(float(max_points) * float(per_submap_factor) / num_submaps)))
        else:
            per_submap_cap = 0

        point_parts = []
        color_parts = []
        for submap_i, submap in enumerate(submaps):
            stride = max(1, int(point_stride))
            points = submap.get_points_in_world_frame(stride=stride)
            colors = submap.get_points_colors(stride=stride)
            n_raw = int(points.reshape(-1, 3).shape[0])
            points, colors = sample_points(points, colors, max_points=per_submap_cap, seed=int(seed) + 1009 * (submap_i + 1))
            if float(voxel_size) > 0:
                points, colors = voxel_downsample_numpy(points, colors, float(voxel_size))
            if points.shape[0] > 0:
                point_parts.append(points)
                color_parts.append(colors)
            print(
                f"[VGGT-SLAM][POINTS] submap={submap.get_id()} "
                f"raw={n_raw:,} sampled={points.shape[0]:,} stride={stride}"
            )
            del points, colors

        if point_parts:
            points = np.concatenate(point_parts, axis=0)
            colors = np.concatenate(color_parts, axis=0)
        else:
            points = np.empty((0, 3), dtype=np.float32)
            colors = np.empty((0, 3), dtype=np.uint8)

        points, colors = sample_points(points, colors, max_points=int(max_points), seed=int(seed))
        if float(voxel_size) > 0:
            points, colors = voxel_downsample_numpy(points, colors, float(voxel_size))
        print(
            f"[VGGT-SLAM][POINTS] collected sampled global point cloud: "
            f"points={points.shape[0]:,}, max_points={int(max_points)}, "
            f"voxel_size={float(voxel_size)}, point_stride={int(point_stride)}"
        )
        return points.astype(np.float32), colors.astype(np.uint8)

    graph_map.collect_sampled_points = types.MethodType(collect_sampled_points, graph_map)


def run_vggt_slam(args: argparse.Namespace, prepared_dir: Path) -> Tuple[Solver, List[str], Dict[str, object]]:
    use_optical_flow_downsample = not args.disable_keyframe_selection
    device = "cuda" if torch.cuda.is_available() and str(args.device).lower() != "cpu" else "cpu"
    print(f"Using device: {device}")

    configure_vggt_slam_runtime(torch_hub_dir=args.torch_hub_dir, offline=args.offline)
    solver = Solver(
        init_conf_threshold=args.conf_threshold,
        use_point_map=args.use_point_map,
        use_sim3=args.use_sim3,
        gradio_mode=False,
        vis_stride=args.vis_stride,
        vis_point_size=args.vis_point_size,
        headless=args.headless,
    )
    ensure_collect_sampled_points(solver.map)

    print("Initializing and loading VGGT model...")
    model = build_vggt_from_local_path(vggt_repo=args.vggt_repo, default_relative_path="vggt")
    load_vggt_weights(model, model_path=args.vggt_model_path, offline=args.offline)
    model.eval()
    model = model.to(device)

    processing_time_start = time.perf_counter()
    print(f"Loading images from {prepared_dir}...")
    image_names = [
        f for f in os.listdir(prepared_dir)
        if Path(f).suffix.lower() in IMAGE_EXTS
        and "depth" not in f.lower()
        and "txt" not in f.lower()
        and "db" not in f.lower()
    ]
    image_names = [str(prepared_dir / f) for f in image_names]
    image_names = utils.sort_images_by_number(image_names)
    image_names = utils.downsample_images(image_names, args.downsample_factor)
    print(f"Found {len(image_names)} images")

    image_names_subset: List[str] = []
    for image_name in tqdm(image_names):
        if use_optical_flow_downsample:
            img = cv2.imread(image_name)
            enough_disparity = solver.flow_tracker.compute_disparity(img, args.min_disparity, args.vis_flow)
            if enough_disparity:
                image_names_subset.append(image_name)
        else:
            image_names_subset.append(image_name)

        if len(image_names_subset) == args.submap_size + args.overlapping_window_size or image_name == image_names[-1]:
            print(image_names_subset)
            predictions = solver.run_predictions(image_names_subset, model, args.max_loops)
            solver.add_points(predictions)
            solver.graph.optimize()
            solver.map.update_submap_homographies(solver.graph)

            loop_closure_detected = len(predictions["detected_loops"]) > 0
            if args.vis_map:
                if loop_closure_detected:
                    solver.update_all_submap_vis()
                else:
                    solver.update_latest_submap_vis()
            image_names_subset = image_names_subset[-args.overlapping_window_size:]

    processing_time_seconds = time.perf_counter() - processing_time_start
    timing_payload = {
        "schema": "processing_time_v1",
        "method": "vggt-slam",
        "processing_time_seconds": float(processing_time_seconds),
        "processing_time_ms": float(processing_time_seconds * 1000.0),
        "start_event": "after_vggt_weights_loaded",
        "end_event": "before_source_internal_export",
        "excluded": ["weight_loading", "final_result_saving"],
        "num_input_images": int(len(image_names)),
        "num_submaps": int(solver.map.get_num_submaps()),
        "num_loop_closures": int(solver.graph.get_num_loops()),
    }
    print(f"Processing time (excluding weights/final saving): {processing_time_seconds:.6f}s")
    print("Total number of submaps in map", solver.map.get_num_submaps())
    print("Total number of loop closures in map", solver.graph.get_num_loops())
    return solver, image_names, timing_payload


def parse_args(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--method", default="vggt-slam")
    parser.add_argument("--scene_dir", required=True)
    parser.add_argument("--output_rrd", required=True)
    parser.add_argument("--output_dir", default=None)
    parser.add_argument("--device", default="auto")
    parser.add_argument("--seed", type=int, default=0)

    parser.add_argument("--images_dir", default="images")
    parser.add_argument("--cams_dir", default="cams")
    parser.add_argument("--depth_dir", default="depth")
    parser.add_argument("--frame_glob", default="*")
    parser.add_argument("--num_views", type=int, default=0)
    parser.add_argument("--start", type=int, default=0)
    parser.add_argument("--stride", type=int, default=1)
    parser.add_argument("--max_side", type=int, default=0)
    parser.add_argument("--size_multiple", type=int, default=14)
    parser.add_argument("--copy_images", action="store_true")

    parser.add_argument("--depth_scale", type=float, default=1.0)
    parser.add_argument("--depth_min", type=float, default=1e-6)
    parser.add_argument("--depth_max", type=float, default=1e6)

    parser.add_argument("--submap_size", type=int, default=16)
    parser.add_argument("--overlapping_window_size", type=int, default=1)
    parser.add_argument("--max_loops", type=int, default=1)
    parser.add_argument("--min_disparity", type=float, default=50.0)
    parser.add_argument("--conf_threshold", type=float, default=25.0)
    parser.add_argument("--vis_map", action="store_true")
    parser.add_argument("--vis_flow", action="store_true")
    parser.add_argument("--headless", action="store_true", default=True)
    parser.add_argument("--no_headless", action="store_false", dest="headless")

    parser.add_argument("--use_sim3", action="store_true")
    parser.add_argument("--plot_focal_lengths", action="store_true")
    parser.add_argument("--downsample_factor", type=int, default=1)
    parser.add_argument("--use_point_map", action="store_true")
    parser.add_argument("--vis_stride", type=int, default=1)
    parser.add_argument("--vis_point_size", type=float, default=0.003)
    parser.add_argument("--disable_keyframe_selection", action="store_true")

    parser.add_argument("--max_pred_points", type=int, default=500000)
    parser.add_argument("--max_gt_points", type=int, default=800000)
    parser.add_argument("--max_points_per_view", type=int, default=500000)
    parser.add_argument("--voxel_downsample", type=float, default=0.01)
    parser.add_argument("--global_point_stride", type=int, default=1)
    parser.add_argument("--no_point_downsample", action="store_false", dest="point_downsample")
    parser.set_defaults(point_downsample=True)
    parser.add_argument("--keep_intermediate", action="store_true")

    parser.add_argument("--vggt_model_path", default=None)
    parser.add_argument("--vggt_repo", default=None)
    parser.add_argument("--torch_hub_dir", default=None)
    parser.add_argument("--offline", action="store_true")
    return parser.parse_args(argv)


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = parse_args(argv)
    if str(args.device).lower() == "cpu":
        os.environ["CUDA_VISIBLE_DEVICES"] = ""
    elif str(args.device).isdigit():
        os.environ["CUDA_VISIBLE_DEVICES"] = str(args.device)
    elif str(args.device).startswith("cuda:") and str(args.device).split(":", 1)[1].isdigit():
        os.environ["CUDA_VISIBLE_DEVICES"] = str(args.device).split(":", 1)[1]

    if str(args.method).replace("_", "-") == "vggt-slam-sim3":
        args.use_sim3 = True

    output_rrd = Path(args.output_rrd).expanduser().resolve()
    output_dir = Path(args.output_dir).expanduser().resolve() if args.output_dir else output_rrd.with_suffix("")
    output_dir.mkdir(parents=True, exist_ok=True)
    prepared_dir = output_dir / "selected_images"

    stems, image_paths = select_images(args)
    prepared_images, prepared_metadata = materialize_images(
        image_paths=image_paths,
        stems=stems,
        out_dir=prepared_dir,
        max_side=int(args.max_side),
        size_multiple=int(args.size_multiple),
        copy_images=bool(args.copy_images),
    )
    print(f"Selected {len(prepared_images)} images for VGGT-SLAM source export; prepared input: {prepared_dir}")

    if prepared_metadata:
        gt_target_h = int(prepared_metadata[0]["prepared_size"]["height"])
        gt_target_w = int(prepared_metadata[0]["prepared_size"]["width"])
    else:
        gt_target_h = 0
        gt_target_w = 0

    print(
        f"[VGGT-SLAM][GT] spatial-compatible target size: "
        f"{gt_target_h}x{gt_target_w}, "
        f"max_side={int(args.max_side)}, size_multiple={int(args.size_multiple)}"
    )

    solver, image_names, timing_payload = run_vggt_slam(args, prepared_dir=prepared_dir)
    timing_path = output_dir / "processing_time.json"
    timing_path.write_text(json.dumps(json_safe(timing_payload), indent=2), encoding="utf-8")

    # Save small pose log for debugging only. Final metric inputs are eval/*.npz/ply.
    pose_log_path = output_dir / "poses.txt"
    solver.map.write_poses_to_file(str(pose_log_path))

    max_pred_points = int(args.max_points_per_view if args.point_downsample else args.max_pred_points)
    voxel_size = float(args.voxel_downsample if args.point_downsample else 0.0)

    meta = export_solver_outputs(
        solver=solver,
        image_names=image_names,
        output_rrd=output_rrd,
        eval_dir=output_dir / "eval",
        scene_dir=Path(args.scene_dir).expanduser().resolve(),
        images_dir=args.images_dir,
        cams_dir=args.cams_dir,
        depth_dir=args.depth_dir,
        depth_scale=float(args.depth_scale),
        depth_min=float(args.depth_min),
        depth_max=float(args.depth_max),
        max_pred_points=max_pred_points,
        max_gt_points=int(args.max_gt_points),
        voxel_size=voxel_size,
        point_stride=int(args.global_point_stride),
        seed=int(args.seed),
        processing_time=timing_payload,
        method="vggt-slam",
        method_variant="sim3" if bool(args.use_sim3) else "sl4",
        gt_target_h=gt_target_h,
        gt_target_w=gt_target_w,
        max_side=int(args.max_side),
        size_multiple=int(args.size_multiple),
    )

    sidecar = output_rrd.with_suffix(".json")
    payload = {
        "method": "vggt-slam",
        "requested_method": args.method,
        "method_variant": "sim3" if bool(args.use_sim3) else "sl4",
        "scene_dir": str(Path(args.scene_dir).expanduser().resolve()),
        "output_rrd": str(output_rrd),
        "output_dir": str(output_dir),
        "prepared_dir": str(prepared_dir),
        "pose_log_path": str(pose_log_path),
        "timing_path": str(timing_path),
        "processing_time": timing_payload,
        "export": meta,
        "stems": stems,
        "prepared_images": prepared_metadata,
    }
    sidecar.write_text(json.dumps(json_safe(payload), indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Saved sidecar metadata: {sidecar}")

    if not args.keep_intermediate:
        try:
            shutil.rmtree(prepared_dir)
            print(f"[CLEANUP] removed directory: {prepared_dir}")
        except Exception as exc:
            print(f"[CLEANUP][WARN] failed to remove {prepared_dir}: {exc}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
